        finally_ran.append(("sgen", FlowRunContext.get() is not None))


@flow(name="agen", on_completion=[on_completion], on_failure=[on_failure])
async def async_gen():
    run_ids["agen"] = FlowRunContext.get().flow_run.id
    try:
