            break

    g = async_gen()
    async for i in g:
        if i == 1:
            break
    await g.aclose()

    async with get_client() as client:
        for name in ("sgen", "agen"):
            run = await client.read_flow_run(run_ids[name])
            history = await client.read_flow_run_states(run_ids[name])

