fn reput_after_expiry_keeps_the_newest_entry() {
    let store = InMemoryCcrStore::with_capacity_and_ttl(2, Duration::from_millis(30));
    store.put("a", "old");
    std::thread::sleep(Duration::from_millis(60));
    assert_eq!(store.get("a"), None);       // expired, removed from the map, still in `order`
    store.put("b", "2");
    store.put("a", "fresh");                // now the newest entry
    store.put("c", "3");                    // at capacity: should evict b
    assert_eq!(store.get("a").as_deref(), Some("fresh"));
}

